begin;
do $courseimport$
declare
 payload jsonb := $coursedata${"course": {"id": "00d22f7c-a06f-52b5-84d2-45569901ca4b", "slug": "cs-101-customer-service-fundamentals", "version": 1, "title": "Customer Service Fundamentals", "description": "Learn how to welcome customers, understand their needs, offer honest help, handle concerns, and end interactions well.", "category": "Customer Experience & Sales", "passing_percent": 80}, "lessons": [{"id": "38b34fc6-1693-5dd8-9411-ead26fe93c64", "position": 1, "title": "Make Every Customer Feel Welcome", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers may feel unsure when they enter a hardware store. A friendly greeting helps them feel comfortable. It also shows that help is available."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Start with a greeting"}, {"type": "paragraph", "text": "Look up when a customer approaches. Use a friendly tone. Say hello and offer help. Give the customer space if they prefer to browse."}, {"type": "heading", "text": "Respect different shopping styles"}, {"type": "paragraph", "text": "Some customers know the exact item they need. Others need time to think. Do not assume that every customer wants a long conversation."}, {"type": "heading", "text": "Stay available"}, {"type": "paragraph", "text": "A customer may decline help at first. Let them know where to find you. Check back when it makes sense. Do not follow them around the store."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer enters and looks at the aisle signs. You say, “Welcome! Can I help you find something?” The customer says they want to look around. You reply, “Of course. I’ll be near the front if you need anything.”"}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Greet customers in a friendly voice."}, {"type": "bullet", "text": "Offer help with a simple question."}, {"type": "bullet", "text": "Respect a customer who wants to browse."}, {"type": "bullet", "text": "Stay easy to find."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Ignoring a customer because you are stocking shelves."}, {"type": "bullet", "text": "Asking too many questions after a customer declines help."}, {"type": "bullet", "text": "Assuming a customer knows where products are located."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker or manager if you cannot leave an assigned station or if customers need help in another area."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "A greeting sets the tone."}, {"type": "bullet", "text": "Offer help without pressure."}, {"type": "bullet", "text": "Respect the customer’s pace."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L01-P01"}, {"type": "paragraph", "text": "Question: A customer says, “I’m just looking.” What should you do?"}, {"type": "paragraph", "text": "A. Follow them and explain every aisle."}, {"type": "paragraph", "text": "B. Say, “No problem. Let me know if you need help.”"}, {"type": "paragraph", "text": "C. Walk away without speaking."}, {"type": "paragraph", "text": "D. Ask why they came to the store."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Respect the customer’s choice. Stay available without pressuring them."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "2d6de14b-d2c1-5f20-b679-171aecdf3081", "position": 2, "title": "Listen Before You Recommend", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers often describe a problem instead of naming a product. Good questions help employees understand the job before suggesting an item."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Learn the goal"}, {"type": "paragraph", "text": "Start with the project. Ask, “What are you working on?” Let the customer finish their explanation."}, {"type": "heading", "text": "Ask one useful question at a time"}, {"type": "paragraph", "text": "Ask about the material, location, or existing part. Use words the customer understands. Avoid a long list of questions."}, {"type": "heading", "text": "Repeat the need"}, {"type": "paragraph", "text": "Summarize what you heard. You might say, “You need a way to hang a picture on a plaster wall. Is that right?” This gives the customer a chance to correct you."}, {"type": "heading", "text": "Avoid guessing"}, {"type": "paragraph", "text": "Similar products may serve different purposes. Check labels and instructions. Ask for help when product suitability is uncertain."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer asks for “the glue for outside.” You ask what they are joining and where the repair will be used. The customer says they need to repair a wooden planter. You check product labels before suggesting options."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Ask about the project first."}, {"type": "bullet", "text": "Listen without interrupting."}, {"type": "bullet", "text": "Confirm your understanding."}, {"type": "bullet", "text": "Verify product details before recommending an item."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Recommending the first familiar product."}, {"type": "bullet", "text": "Using technical words without explaining them."}, {"type": "bullet", "text": "Treating a customer’s first description as complete."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a knowledgeable coworker or refer to official product instructions when the application is unclear. Refer specialized or regulated work to a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Understand the job before naming a product."}, {"type": "bullet", "text": "Ask clear questions."}, {"type": "bullet", "text": "Confirm what you heard."}, {"type": "bullet", "text": "Never guess about suitability."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L02-P01"}, {"type": "paragraph", "text": "Question: A customer asks for “a screw for my deck.” What is the best first step?"}, {"type": "paragraph", "text": "A. Hand them any wood screw."}, {"type": "paragraph", "text": "B. Ask what material they are fastening and where it will be used."}, {"type": "paragraph", "text": "C. Tell them all screws are alike."}, {"type": "paragraph", "text": "D. Send them to checkout."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: The material and location help narrow the choice. Do not recommend a fastener before learning the project details."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "863ba92b-b012-551d-9511-5e2378d78597", "position": 3, "title": "Give Clear and Honest Help", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers need information they can use. Clear words and honest answers build confidence. Guessing can cause mistakes and frustration."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Use everyday language"}, {"type": "paragraph", "text": "Name the aisle or product group. Point out a label or feature. Explain unfamiliar terms in simple words."}, {"type": "heading", "text": "Be honest about limits"}, {"type": "paragraph", "text": "You do not need to know every answer. Say, “I want to check that before I recommend it.” Then use an approved resource or ask a coworker."}, {"type": "heading", "text": "Make a useful handoff"}, {"type": "paragraph", "text": "Explain the customer’s question to the next employee. Stay with the customer when practical. Do not send them from person to person without context."}, {"type": "heading", "text": "Avoid promises you cannot confirm"}, {"type": "paragraph", "text": "Check inventory, service availability, and delivery details before making a promise. Store systems and procedures vary."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer wants to know whether a particular light bulb works with a dimmer. You check the package. The label is unclear. You say, “Let me verify that before you buy it.” You ask a trained coworker to help."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Use short, clear explanations."}, {"type": "bullet", "text": "Show where to find product information."}, {"type": "bullet", "text": "Say when you need to verify an answer."}, {"type": "bullet", "text": "Explain the customer’s need during a handoff."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Guessing to sound confident."}, {"type": "bullet", "text": "Giving directions that are too vague."}, {"type": "bullet", "text": "Promising a product or service without checking."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Consult product labels, manufacturer instructions, an experienced coworker, or a manager. Do not give instructions for work that requires a qualified professional."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Clarity matters more than jargon."}, {"type": "bullet", "text": "Honesty builds trust."}, {"type": "bullet", "text": "A good handoff saves time."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L03-P01"}, {"type": "paragraph", "text": "Question: You cannot confirm whether a bulb works with a dimmer. What should you say?"}, {"type": "paragraph", "text": "A. “It probably works.”"}, {"type": "paragraph", "text": "B. “That is not my problem.”"}, {"type": "paragraph", "text": "C. “Let me check the product information and ask someone who knows.”"}, {"type": "paragraph", "text": "D. “All LED bulbs work with dimmers.”"}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: Verify compatibility instead of guessing. The package and manufacturer information can help."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "37c47c5d-f52e-58c5-9e6d-f1581411dc99", "position": 4, "title": "Handle Frustration with Respect", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "Customers sometimes face delays, missing products, or confusing information. A calm response can keep a problem from getting worse."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Listen first"}, {"type": "paragraph", "text": "Let the customer explain the concern. Keep your voice steady. Avoid interrupting or arguing."}, {"type": "heading", "text": "Acknowledge the problem"}, {"type": "paragraph", "text": "Show that you understand the inconvenience. You might say, “I can see why that is frustrating.” Do not promise a result before you know what is possible."}, {"type": "heading", "text": "Offer a clear next step"}, {"type": "paragraph", "text": "Check the facts. Explain the options allowed by store policy. Ask a manager to help with decisions outside your authority."}, {"type": "heading", "text": "Protect everyone’s safety"}, {"type": "paragraph", "text": "Do not accept threats or abusive behavior as part of the job. Follow store procedures. Get a manager or emergency help when needed."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "A customer says a special-order item has not arrived. You listen and acknowledge the delay. You check the order status through the approved process. You explain what you can confirm and ask a manager to assist with options."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Stay calm and listen."}, {"type": "bullet", "text": "Acknowledge the concern without blame."}, {"type": "bullet", "text": "Check facts before offering a solution."}, {"type": "bullet", "text": "Escalate issues beyond your authority."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Arguing about who caused the problem."}, {"type": "bullet", "text": "Promising a refund or delivery date without approval."}, {"type": "bullet", "text": "Taking an angry comment personally."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Involve a manager for policy exceptions, refund disputes, repeated complaints, threats, or unsafe behavior. Follow the store’s incident and emergency procedures."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Listen before responding."}, {"type": "bullet", "text": "Acknowledge frustration."}, {"type": "bullet", "text": "Offer only confirmed options."}, {"type": "bullet", "text": "Get help when needed."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L04-P01"}, {"type": "paragraph", "text": "Question: A customer is upset about a delayed order. What is the best first response?"}, {"type": "paragraph", "text": "A. Tell them delays happen everywhere."}, {"type": "paragraph", "text": "B. Listen, acknowledge the concern, and check the order status."}, {"type": "paragraph", "text": "C. Promise the order will arrive tomorrow."}, {"type": "paragraph", "text": "D. Tell them to contact the supplier directly."}, {"type": "paragraph", "text": "Answer: B"}, {"type": "paragraph", "text": "Explanation: Listening and checking facts create a useful next step. Do not promise dates that are not confirmed."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}, {"id": "f02829db-f96a-58b6-ab36-681db7f135e8", "position": 5, "title": "Finish the Interaction Well", "body": [{"type": "heading", "text": "Why this matters"}, {"type": "paragraph", "text": "A helpful conversation can still end poorly if the customer does not know what happens next. A clear close reduces confusion."}, {"type": "heading", "text": "Lesson content"}, {"type": "heading", "text": "Confirm the result"}, {"type": "paragraph", "text": "Ask whether the customer found what they need. If another person will help, explain who and where."}, {"type": "heading", "text": "Be clear about follow-up"}, {"type": "paragraph", "text": "For orders or services, share only verified details. Explain how the customer will receive updates under the store’s process."}, {"type": "heading", "text": "Offer one final opportunity"}, {"type": "paragraph", "text": "Ask, “Is there anything else I can help you find?” Do not pressure the customer to buy more."}, {"type": "heading", "text": "Thank the customer"}, {"type": "paragraph", "text": "End with a friendly thank-you. A simple close shows respect for their time."}, {"type": "heading", "text": "Hardware-store example"}, {"type": "paragraph", "text": "You help a customer locate a paint roller. They also need a tray. You show them the tray options. You ask whether they need anything else. The customer says no. You thank them and point out the checkout area."}, {"type": "heading", "text": "What to say or do"}, {"type": "bullet", "text": "Confirm the customer’s next step."}, {"type": "bullet", "text": "Check whether more help is needed."}, {"type": "bullet", "text": "Avoid unverified promises."}, {"type": "bullet", "text": "Thank the customer."}, {"type": "heading", "text": "Common mistakes"}, {"type": "bullet", "text": "Leaving without saying what happens next."}, {"type": "bullet", "text": "Assuming the customer has everything they need."}, {"type": "bullet", "text": "Using a sales pitch when the customer is ready to leave."}, {"type": "heading", "text": "When to ask for help"}, {"type": "paragraph", "text": "Ask a coworker or manager when an order, service, or complaint still needs follow-up. Confirm who owns the next step."}, {"type": "heading", "text": "Key takeaways"}, {"type": "bullet", "text": "Make the next step clear."}, {"type": "bullet", "text": "Offer more help without pressure."}, {"type": "bullet", "text": "End with a thank-you."}, {"type": "heading", "text": "Unscored lesson practice"}, {"type": "paragraph", "text": "Question ID: CS-101-L05-P01"}, {"type": "paragraph", "text": "Question: A coworker will finish helping your customer. What should you do before leaving?"}, {"type": "paragraph", "text": "A. Walk away as soon as the coworker arrives."}, {"type": "paragraph", "text": "B. Tell the customer to explain everything again."}, {"type": "paragraph", "text": "C. Brief the coworker and confirm the customer knows who will help."}, {"type": "paragraph", "text": "D. Promise the coworker can solve every problem."}, {"type": "paragraph", "text": "Answer: C"}, {"type": "paragraph", "text": "Explanation: A clear handoff helps the customer avoid repeating the full story. Confirm who will take over."}, {"type": "heading", "text": "Optional practice"}, {"type": "paragraph", "text": "None assigned. The lesson question above is unscored."}]}], "questions": [{"id": "92de1f24-d044-5a55-8de3-144fdfa663f5", "position": 1, "prompt": "A customer enters and says they want to browse. What is the best response?", "options": ["Explain every department before they start.", "Respect their choice and tell them where to find help.", "Ignore them for the rest of the visit.", "Ask them to name a product before entering."], "correct_option": 1, "explanation": "A friendly greeting and a low-pressure offer of help respect the customer’s choice."}, {"id": "f23979f7-a3a0-5174-9091-5f8cf2c680f2", "position": 2, "prompt": "A customer asks for tape to repair something outdoors. What should you do first?", "options": ["Recommend the first tape on the shelf.", "Tell them all tape works outdoors.", "Ask what material they need to repair and what conditions it faces.", "Send them to the paint department without asking questions."], "correct_option": 2, "explanation": "Ask about the material and conditions. These details help narrow the options. Do not guess based on a broad request."}, {"id": "67232f80-4839-57e3-b3cb-81372f73b647", "position": 3, "prompt": "You are unsure whether a replacement part fits a customer’s tool. What is the best response?", "options": ["Say it fits because it looks similar.", "Check the model information and approved product resources before answering.", "Tell the customer to buy it and try it.", "Avoid the customer until another employee arrives."], "correct_option": 1, "explanation": "Verify model and product information before recommending a replacement. Appearance alone does not confirm compatibility."}, {"id": "67692e97-7788-5415-872f-46ff1b3b55bf", "position": 4, "prompt": "A customer is upset about a return decision. You do not have authority to change it. What should you do?", "options": ["Argue until they agree with you.", "Promise an exception without approval.", "Listen calmly, explain what you can confirm, and involve a manager.", "Walk away without telling anyone."], "correct_option": 2, "explanation": "Listen and explain confirmed information. A manager should handle decisions outside your authority."}, {"id": "56d09b36-d2db-5662-b83a-13a6a6d4af36", "position": 5, "prompt": "You have helped a customer find the right aisle. What is a good way to finish?", "options": ["Leave immediately without checking.", "Ask if they need anything else and thank them.", "Insist that they buy another item.", "Promise a discount for their visit."], "correct_option": 1, "explanation": "A short check-in and thank-you give the interaction a clear, respectful ending."}], "catalog": {"course_code": "CS-101", "skill_level": "foundations", "topics": ["Customer Service"], "keywords": ["Make Every Customer Feel Welcome", "Listen Before You Recommend", "Give Clear and Honest Help", "Handle Frustration with Respect", "Finish the Interaction Well", "Why this matters", "Lesson content", "Start with a greeting", "Respect different shopping styles", "Stay available", "Hardware-store example", "What to say or do", "Common mistakes", "When to ask for help", "Key takeaways", "Unscored lesson practice", "Optional practice", "Learn the goal", "Ask one useful question at a time", "Repeat the need", "Avoid guessing", "Use everyday language", "Be honest about limits", "Make a useful handoff", "Avoid promises you cannot confirm", "Listen first", "Acknowledge the problem", "Offer a clear next step", "Protect everyone’s safety", "Confirm the result", "Be clear about follow-up", "Offer one final opportunity", "Thank the customer", "CS-101-", "ID", "L01-P01", "L02-P01", "L03-P01", "L04-P01", "L05-P01", "LED"], "learning_paths": ["New Retail Employee"]}}$coursedata$::jsonb;
 c jsonb; l jsonb; q jsonb; target uuid;
begin
 c := payload->'course'; target := (c->>'id')::uuid;
 perform pg_advisory_xact_lock(hashtextextended('coltrain-course:' || target::text, 0));
 if exists(select 1 from public.training_courses where id=target) then
  if not exists(select 1 from public.training_courses t where t.id=target
   and t.slug=c->>'slug' and t.version=(c->>'version')::integer
   and t.title=c->>'title' and t.description=c->>'description'
   and t.category=c->>'category' and t.passing_percent=(c->>'passing_percent')::integer
   and t.owner_organization_id is null) then
   raise exception 'CS-101 course differs; create a new version rather than overwrite';
  end if;
  if (select count(*) from public.training_lessons where course_id=target) <> jsonb_array_length(payload->'lessons')
   or (select count(*) from public.training_questions where course_id=target) <> jsonb_array_length(payload->'questions') then
   raise exception 'CS-101 content differs; draft import was not changed';
  end if;
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   if not exists(select 1 from public.training_lessons t where t.id=(l->>'id')::uuid
    and t.course_id=target and t.position=(l->>'position')::integer
    and t.title=l->>'title' and t.body=l->'body') then
    raise exception 'CS-101 lesson differs; draft import was not changed';
   end if;
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   if not exists(select 1 from public.training_questions t join private.training_answer_keys k on k.question_id=t.id
    where t.id=(q->>'id')::uuid and t.course_id=target and t.position=(q->>'position')::integer
    and t.prompt=q->>'prompt' and t.options=q->'options'
    and k.correct_option=(q->>'correct_option')::integer and k.explanation=q->>'explanation') then
    raise exception 'CS-101 question differs; draft import was not changed';
   end if;
  end loop;
 else
  insert into public.training_courses(id,slug,version,title,description,category,passing_percent,published)
   values(target,c->>'slug',(c->>'version')::integer,c->>'title',c->>'description',c->>'category',(c->>'passing_percent')::integer,false);
  for l in select value from jsonb_array_elements(payload->'lessons') loop
   insert into public.training_lessons(id,course_id,position,title,body)
    values((l->>'id')::uuid,target,(l->>'position')::integer,l->>'title',l->'body');
  end loop;
  for q in select value from jsonb_array_elements(payload->'questions') loop
   insert into public.training_questions(id,course_id,position,prompt,options)
    values((q->>'id')::uuid,target,(q->>'position')::integer,q->>'prompt',q->'options');
   insert into private.training_answer_keys(question_id,correct_option,explanation)
    values((q->>'id')::uuid,(q->>'correct_option')::integer,q->>'explanation');
  end loop;
 end if;
 -- Optional metadata: imports remain compatible before the catalog migration.
 if to_regclass('public.training_course_catalog') is not null then
  insert into public.training_course_catalog(course_id,course_code,skill_level,topics,keywords,learning_paths)
  values(target,payload->'catalog'->>'course_code',payload->'catalog'->>'skill_level',
   array(select jsonb_array_elements_text(payload->'catalog'->'topics')),
   array(select jsonb_array_elements_text(payload->'catalog'->'keywords')),
   array(select jsonb_array_elements_text(payload->'catalog'->'learning_paths')))
  on conflict(course_id) do nothing;
 end if;
end;
$courseimport$;
commit;
select slug,title,published,
 (select count(*) from public.training_lessons where course_id=c.id) as lessons,
 (select count(*) from public.training_questions where course_id=c.id) as quiz_questions
from public.training_courses c where id='00d22f7c-a06f-52b5-84d2-45569901ca4b';
